using System;
class Checks { static void Main() {foreach(float source in new[]{40f,50f,75f,84f}) foreach(float target in new[]{60f,84f,100f}) foreach(bool nested in new[]{false,true}) {var label=RebirthItemPreviewLayout.Place(0,0,source,0,0,target,10,-30,24,true,false,nested);float effective=label.FontSize*label.Scale*(nested?target/source:1);if(Math.Abs(effective-24)>target/source*.51f)throw new Exception("Quality font grows with hero icon");}Console.WriteLine("PASS: actual preview layout keeps quality text at native source font size across 24 size/nesting cases (rounding tolerance).");} }
